  add('prep',Math.min(5,Math.max(3,Math.round(duration*.08))),'Vorbereitung',`Ausrüstung prüfen, Quests sammeln und ${c.name} auf den nächsten Abschnitt vorbereiten.`, 'Vorbereitung');
  let remaining=duration-tasks[0].mins;
  const dungeonPossible=!!d&&remaining>=40;
  if(focus==='Dungeon'&&dungeonPossible||focus==='Auto'&&dungeonPossible&&duration>=75){const run=focus==='Dungeon'?Math.min(remaining,55):Math.min(55,Math.round(remaining*.7));add('dungeon',run,`${d.name} – Dungeonquests & Loot`,'Gezielter Run; die Dauer variiert mit Gruppe und Anreise. Keine garantierte Abschlusszeit.', 'Dungeon');remaining-=run;}
  if(focus==='Loot'&&dungeonPossible&&d&&tasks.every(t=>t.id!=='dungeon')){const run=Math.min(remaining,50);add('dungeon',run,`Gezielt ${d.name} besuchen`,'Nur für passende Boss-/Questdrops und wenn eine Gruppe verfügbar ist.', 'Loot');remaining-=run;}
  if(focus==='Berufe'&&farm){const chunk=Math.min(remaining,Math.max(10,Math.round(remaining*.72)));add('prof',chunk,`Materialien: ${farm.item}`,`${farm.zone}: ${farm.spot}. ${farm.tip}`, 'Berufe');remaining-=chunk;}
  if(focus==='Gold'&&farm){const chunk=Math.min(remaining,Math.max(10,Math.round(remaining*.73)));add('farm',chunk,`Farmrunde ${farm.zone}`,`${farm.item}. Marktpreise und tatsächlicher Ertrag sind nicht bekannt.`, 'Gold');remaining-=chunk;}
  if((focus==='Auto'||focus==='XP'||focus==='Loot'||focus==='Dungeon'&&!dungeonPossible)&&remaining>=8){const chunk=Math.min(remaining,Math.max(8,Math.round(remaining*.72)));add('quests',chunk,`Questen in ${zone}`,`Questhubs bündeln und Kämpfe sinnvoll mit deinem ${cur().title}-Build kombinieren.`, 'XP');remaining-=chunk;}
  if(remaining>=5&&farm){const chunk=remaining;add('materials',chunk,`${farm.category}: ${farm.item}`,`${farm.zone} · ${farm.spot}. Nur auf der Route farmen, keine feste Gold-/XP-Rate angenommen.`,farm.category);remaining-=chunk;}
  if(remaining>0){add('flex',remaining,'Puffer / Wegezeit','Für Laufwege, Reparaturen oder eine spontane Nebenquest.', 'Flexibel');}
  return tasks;
